class Solution(object):
    def getHint(self, secret, guess):
        """
        :type secret: str
        :type guess: str
        :rtype: str
        """
        n = len(secret)
        d1, d2 = collections.defaultdict(int), collections.defaultdict(int)
        ans1, ans2 = 0, 0
        for i in range(n):
            if secret[i] == guess[i]:
                ans1 += 1
            else:
